package com.aitu.lms.visitor;
import com.aitu.lms.domain.*; import java.util.*;
public final class StudentFilterVisitor implements Visitor<List<Student>> { private final double minGpa; public StudentFilterVisitor(double minGpa){this.minGpa=minGpa;} private List<Student> merge(List<Student> a, List<Student> b){var r=new ArrayList<>(a);r.addAll(b);return r;} public List<Student> visitFaculty(Faculty x){var r=new ArrayList<Student>();for(Element e:x.children())r.addAll(e.accept(this));return r;} public List<Student> visitProgram(Program x){var r=new ArrayList<Student>();for(Element e:x.children())r.addAll(e.accept(this));return r;} public List<Student> visitCourse(Course x){var r=new ArrayList<Student>();for(Element e:x.children())r.addAll(e.accept(this));return r;} public List<Student> visitLecture(Lecture x){return List.of();} public List<Student> visitLab(Lab x){return List.of();} public List<Student> visitExam(Exam x){return List.of();} public List<Student> visitStudent(Student x){return x.gpa()>=minGpa?List.of(x):List.of();} }
